  "assumptions": [
    {
      "id": "A-01",
      "text": "No existing AWS Organization or Control Tower deployment exists for Northstar Facilities Group; this is a net-new greenfield landing zone.",
      "reason": "The SRS makes no reference to an existing AWS account structure, Organization, or Control Tower."
    },
    {
      "id": "A-02",
      "text": "The 30-day log retention stated in NFR-09 applies to application-level logs (CloudWatch Logs). The landing-zone CloudTrail and AWS Config logs in Log Archive are retained for the default 365 days.",
      "reason": "NFR-09 specifies 30 days for application errors and processing failures; no shorter retention is stated for audit/compliance logs."
    },
    {
      "id": "A-03",
      "text": "The RTO of 8 hours and RPO of 24 hours (NFR-05) are met by AWS Backup snapshots within the single us-east-1 Region. No DR region or second VPC is required.",
