    },
    {
      "id": "A-05",
      "text": "The non-production account covers both development and testing stages. No separate Dev or Test OU is needed because the SRS states no different policies per stage.",
      "reason": "The SRS defines a single non-production environment with no policy differentiation between dev and test."
    },
    {
      "id": "A-06",
      "text": "The workload uses AWS-native managed services (Cognito or IAM Identity Center for app auth, RDS or DynamoDB, SES, Lambda/ECS, ALB) consistent with C-02. The landing zone does not prescribe specific services.",
      "reason": "C-02 mandates AWS-native managed services only; the landing zone provides the account and network scaffold."
    }
  ],
