  "workload_owns": [
    "public entry point (ALB, WAF)",
    "KMS keys for its data",
    "CloudWatch logs and alarms",
    "AWS Backup plans",
    "application IAM roles"
  ],
  "lz_version": 1,
  "lz_hash": "f9fff5e1fd38f60b"
}

