      "prefilled": true
    },
    {
      "id": "vpc_prod_public",
      "type": "subnet",
      "name": "Public subnets",
      "parent": "vpc_prod",
      "cidr": "",
      "tier": "public",
      "azs": [
        "us-east-1a"
      ],
