        "10.0.0.0/24"
      ],
      "account": "northstar-maintenance-portal-prod",
      "region": "us-east-1",
      "prefilled": true
    },
    {
      "id": "vpc_prod_private_app",
      "type": "subnet",
      "name": "App subnets",
